import * as T from 'three';
import {createToyKit} from '../world/toy-kit.js';
import {compactStaticGeometry} from './compact-static.js';
import {HARBOR_LIGHTHOUSE as L,HARBOR_SEAT as S} from './harbor-lighthouse-layout.js';
export function buildHarborLighthouse(parent){const root=new T.Group();root.name='harbor.lighthouse-and-seat';parent.add(root);const kit=createToyKit(root),tower=new T.Group();tower.name='harbor.lighthouse';tower.position.set(L.x,0,L.z);tower.rotation.y=Math.atan2(S.anchor.x-L.x,S.anchor.z-L.z);root.add(tower);const cyl=(a,b,h,color,y)=>kit.cylinder(a,b,h,color,0,y,0,tower);
 cyl(.72,.76,.20,'#d6d9ce',.125);cyl(.50,.63,2.42,'#f5ead3',1.41);cyl(.59,.61,.34,'#a9c5bb',1.16);cyl(.74,.68,.13,'#a9c5bb',2.67);const lantern=cyl(.46,.46,.65,'#f0e4ba',3.04);lantern.name='harbor.lighthouse.lantern';lantern.userData.nightLamp=true;for(const angle of[0,Math.PI/2,Math.PI,Math.PI*1.5])kit.cylinder(.028,.028,.72,'#506c7c',Math.sin(angle)*.49,3.045,Math.cos(angle)*.49,tower);cyl(.58,.58,.07,'#506c7c',3.38);cyl(0,.74,.42,'#506c7c',3.615);kit.sphere(.065,'#d0ae6b',0,3.86,0,1,1,1,tower);kit.box(.37,.62,.05,'#64898a',0,.54,.613,.06,tower);kit.box(.09,.09,.03,'#d0ae6b',.09,.54,.647,.02,tower);
 const chair=new T.Group();chair.name='harbor.lighthouse-chair';chair.position.set(S.anchor.x,0,S.anchor.z);chair.rotation.y=S.anchor.yaw;root.add(chair);const seat=kit.box(1.30,.12,.80,'#cda77b',0,.42,0,.035,chair);seat.name='harbor.lighthouse-chair.seat';for(const a of[-.48,.48])for(const b of[-.27,.27])kit.box(.12,.36,.12,'#6f8d82',a,.20,b,.025,chair);kit.box(1.3,.32,.09,'#a9c5bb',0,.74,-.47,.04,chair);for(const a of[-.51,.51])kit.box(.085,.65,.085,'#6f8d82',a,.40,-.47,.02,chair);
 compactStaticGeometry(tower,n=>n!==lantern);compactStaticGeometry(chair,n=>n!==seat);return root;}
